class.description:
A [TextInsertionTemplate] is created by [method TextInsertionServer.parse]. It stores the text as a list of literal parts and placeholders, so [method TextInsertionServer.insert_template] only looks up the values and joins the parts. It also tells which names the text uses, so a label can insert its text again only when one of them changes.
[codeblocks]
[gdscript]
var template = TextInsertionServer.parse("{player} has {gold:number} gold.")

func _ready():
	TextInsertionServer.value_changed.connect(_on_value_changed)
	_refresh()

func _on_value_changed(name):
	if template.has_name(name):
		_refresh()

func _refresh():
	text = TextInsertionServer.insert_template(template)
[/gdscript]
[csharp]
private TextInsertionTemplate _template = TextInsertionServer.Parse("{player} has {gold:number} gold.");

public override void _Ready()
{
	TextInsertionServer.ValueChanged += OnValueChanged;
	Refresh();
}

private void OnValueChanged(StringName name)
{
	if (_template.HasName(name))
	{
		Refresh();
	}
}

private void Refresh()
{
	Text = TextInsertionServer.InsertTemplate(_template);
}
[/csharp]
[/codeblocks]
[b]Note:[/b] A template does not change after parsing and can be used from several threads.
